// TagFacts gathers the tags defined on the targeted Catalyst Center.
//
// It reports system tags and operator tags separately. A Catalyst Center
// creates tags for its own bookkeeping (AUTO_INV_EVENT_SYNC_DISABLED and
// similar), and a runbook grouping devices by operator intent wants the
// ones a human created, not those. Emitting both, labeled, lets the runbook
// decide rather than guessing here.
func TagFacts(ctx context.Context, rc sdk.RunbookContext, device inventory.InventoryItem, params map[string]any) (collection.Result, error) {
	client, err := clientForDevice(rc, device, params)
	if err != nil {
		return collection.Result{}, err
	}
	defer func() { _ = client.Close() }()

	tags, err := client.ListTags(ctx)
	if err != nil {
		return collection.Result{}, fmt.Errorf("net.catalyst.tag_facts: %w", err)
	}

	all := make([]map[string]any, 0, len(tags))
	operator := make([]string, 0, len(tags))
	for _, t := range tags {
		all = append(all, map[string]any{
			"id":         t.ID,
			"name":       t.Name,
			"system_tag": t.SystemTag,
		})
		if !t.SystemTag {
			operator = append(operator, t.Name)
		}
	}

	if err := rc.EmitFact("tags", all); err != nil {
		return collection.Result{}, err
	}
	if err := rc.EmitFact("operator_tags", operator); err != nil {
		return collection.Result{}, err
	}
	return collection.Result{Changed: false}, nil
}
